-- Total page-views per day in Nov-2020 and
-- average page-views per purchasing user on those days
WITH purchase_users AS (
  -- Users who generated at least one purchase in Nov-2020
  SELECT DISTINCT user_pseudo_id
  FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_*`
  WHERE _TABLE_SUFFIX BETWEEN '20201101' AND '20201130'
    AND event_name = 'purchase'
),
day_pageviews AS (
  -- Page-view events in Nov-2020 generated by those purchasing users
  SELECT
    event_date,
    user_pseudo_id
  FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_*`
  WHERE _TABLE_SUFFIX BETWEEN '20201101' AND '20201130'
    AND event_name = 'page_view'
    AND user_pseudo_id IN (SELECT user_pseudo_id FROM purchase_users)
)
SELECT
  event_date,
  COUNT(*)                                                AS total_page_views,
  ROUND(COUNT(*) / COUNT(DISTINCT user_pseudo_id), 4)     AS avg_pageviews_per_user
FROM day_pageviews
GROUP BY event_date
ORDER BY event_date;